--
-- Name: pessoas; Type: TABLE; Schema: public; Owner: sist_user
--

CREATE TABLE public.pessoas (
    id bigint NOT NULL,
    situacao_de_rua character varying(3) NOT NULL,
    nome character varying(255) NOT NULL,
    nis character varying(20),
    nome_social character varying(255),
    certidao_nascimento_data date NOT NULL,
    sexo character varying(5) NOT NULL,
    telefone character varying(20),
    celular character varying(20),
    email character varying(254),
    nome_mae character varying(255),
    indicado_mae_id integer,
    nome_pai character varying(255),
    indicado_pai_id integer,
    pais_id integer,
    codigo_ibge character varying(15),
    certidao_nome_cartorio character varying(255),
    certidao character varying(15),
    certidao_numero_livro_registro character varying(50),
    certidao_folha_livro_registro character varying(50),
    certidao_numero_matricula character varying(100),
    certidao_nascimento character varying(50),
    rani character varying(50),
    certidao_data_registro date,
    certidao_codigo_ibge_registro character varying(15),
    rg character varying(30),
    rg_digito character varying(5),
    rg_data_emissao date,
    rg_orgao_emissor character varying(50),
    cpf character varying(14) NOT NULL,
    rne character varying(30),
    ctps character varying(30),
    ctps_serie character varying(20),
    ctps_data_emissao date,
    titulo_eleitor character varying(30),
    titulo_eleitor_zona character varying(10),
    titulo_eleitor_secao character varying(10),
    cnh character varying(30),
    sus character varying(30),
    reservista character varying(30),
    portador_doenca_grave character varying(3) NOT NULL,
    usa_medicamento_controlado character varying(3) NOT NULL,
    abuso_de_alcool character varying(3) NOT NULL,
    abuso_de_droga character varying(3) NOT NULL,
    medicamento_continuo character varying(3) NOT NULL,
    tratamento_saude character varying(3) NOT NULL,
    escreve_le character varying(3),
    frequenta_escola_creche_id integer,
    nome_escola character varying(255),
    localizada_municipio character varying(3),
    codigo_inep_mec character varying(50),
    nome_curso_frequenta character varying(150),
    curso_concluido character varying(3) NOT NULL,
    trabalha character varying(3),
    afastado_trabalho character varying(3),
    atividade_agricula character varying(3),
    remuneracao_bruta numeric(7,2) NOT NULL,
    receita_ajuda_doacao_regular numeric(7,2) NOT NULL,
    receita_aposentadoria_pensao numeric(7,2) NOT NULL,
    receita_beneficio_prestacao_continuada numeric(7,2) NOT NULL,
    receita_seguro_desemprego numeric(7,2) NOT NULL,
    receita_pensao_alimenticia numeric(7,2) NOT NULL,
    receita_outras_fontes numeric(7,2) NOT NULL,
    recebe_bolsa_familia character varying(3) NOT NULL,
    receita_bolsa_familia numeric(7,2) NOT NULL,
    receita_programa_erradicacao_trabalho_infantil numeric(7,2) NOT NULL,
    observacao text,
    ativo boolean NOT NULL,
    certidao_municipio_registro_id bigint,
    certidao_uf_registro_id bigint,
    ctps_estado_emissor_id bigint,
    estado_id bigint,
    estado_municipio_escola_id bigint,
    familia_domicilio_id bigint,
    municipal_escola_membro_id bigint,
    municipio_id bigint,
    orientacao_sexual_id bigint,
    qualificacao_profissional_cbo_id bigint,
    raca_id bigint,
    rg_uf_id bigint,
    tipo_atividade_id bigint,
    tipo_curso_frequenta_id bigint,
    tipo_curso_frequentou_id bigint,
    tipo_deficiencia_id bigint,
    tipo_estado_civil_id bigint,
    tipo_local_nascimento_id bigint,
    tipo_necessita_cuidados_id bigint,
    tipo_parentesco_id bigint,
    tipo_registro_civil_id bigint,
    tipo_serie_curso_concluido_id bigint,
    tipo_serie_curso_frequenta_id bigint,
    tipo_tratamento_caps_id bigint
);


