CREATE TABLE public.vulnerabilidade_social (
    id bigint NOT NULL,
    nome character varying(255) NOT NULL,
    ativo boolean NOT NULL
);


ALTER TABLE public.vulnerabilidade_social OWNER TO sist_user;

--
-- Name: vulnerabilidade_social_id_seq; Type: SEQUENCE; Schema: public; Owner: sist_user
--

ALTER TABLE public.vulnerabilidade_social ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.vulnerabilidade_social_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


